using System.Formats.Tar; using System.IO.Compression; using System.Net.Http.Headers; using System.Net.NetworkInformation; using System.Net.Sockets; using System.Runtime.InteropServices; using System.Text.Json;
namespace RafaoCluster.CrossPlatform.Services;
public sealed class PlatformService(ProcessRunner runner)
{
 public string DataRoot { get; }=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RafaoCluster");
 public string LlamaRoot=>Path.Combine(DataRoot,"llama"); public string ModelsRoot=>Path.Combine(DataRoot,"models");
 public bool IsMac=>OperatingSystem.IsMacOS(); public bool IsLinux=>OperatingSystem.IsLinux();
 public string PlatformName=>IsMac?$"macOS {RuntimeInformation.OSArchitecture}":$"Linux {RuntimeInformation.OSArchitecture}";
 public string? Find(string name){string[] names=[name];foreach(var n in names){var local=Directory.Exists(LlamaRoot)?Directory.EnumerateFiles(LlamaRoot,n,SearchOption.AllDirectories).FirstOrDefault():null;if(local is not null)return local;foreach(var d in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){var p=Path.Combine(d,n);if(File.Exists(p))return p;}}return null;}
 public async Task<string> DiagnoseAsync(){var lines=new List<string>{$"{Environment.MachineName} · {PlatformName}"};try{if(IsMac){var(code,cpu)=await runner.RunAsync("sysctl",["-n","machdep.cpu.brand_string"]);if(code!=0||string.IsNullOrWhiteSpace(cpu)){(_,cpu)=await runner.RunAsync("sysctl",["-n","hw.model"]);}var(_,mem)=await runner.RunAsync("sysctl",["-n","hw.memsize"]);lines.Add($"{cpu.Trim()} · {double.Parse(mem.Trim())/1073741824d:0.0} GB de memória unificada");}else{var mem=File.ReadLines("/proc/meminfo").FirstOrDefault(x=>x.StartsWith("MemTotal"));lines.Add(mem??"RAM não identificada");var(_,gpu)=await runner.RunAsync("nvidia-smi",["--query-gpu=index,name,memory.total,memory.free,driver_version","--format=csv,noheader"]);lines.Add(gpu.Trim());}}catch(Exception e){lines.Add("GPU/CPU: "+e.Message);}foreach(var n in NetworkInterface.GetAllNetworkInterfaces().Where(x=>x.OperationalStatus==OperationalStatus.Up)){foreach(var a in n.GetIPProperties().UnicastAddresses.Where(x=>x.Address.AddressFamily==AddressFamily.InterNetwork&&!x.Address.ToString().StartsWith("127.")))lines.Add($"{n.Name}: {a.Address} ({n.Speed/1_000_000} Mb/s)");}return string.Join("\n",lines.Where(x=>!string.IsNullOrWhiteSpace(x)));}
 public async Task InstallAsync(Action<string> log){Directory.CreateDirectory(LlamaRoot);if(IsMac){var brew=File.Exists("/opt/homebrew/bin/brew")?"/opt/homebrew/bin/brew":"/usr/local/bin/brew";if(!File.Exists(brew))throw new InvalidOperationException("Homebrew não encontrado. Instale em brew.sh e tente novamente.");log("Instalando llama.cpp pelo Homebrew...");var(r,o)=await runner.RunAsync(brew,["install","llama.cpp"]);log(o);if(r!=0)throw new InvalidOperationException("O Homebrew não conseguiu instalar llama.cpp.");return;}await InstallLinuxRelease(log);}
 private async Task InstallLinuxRelease(Action<string> log){using var http=new HttpClient();http.DefaultRequestHeaders.UserAgent.Add(new ProductInfoHeaderValue("RafaoCluster","0.4"));var json=await http.GetStringAsync("https://api.github.com/repos/ggml-org/llama.cpp/releases?per_page=20");using var doc=JsonDocument.Parse(json);foreach(var rel in doc.RootElement.EnumerateArray()){var assets=rel.GetProperty("assets").EnumerateArray().ToList();var cuda=Find("nvidia-smi") is not null;var asset=assets.FirstOrDefault(a=>{var n=a.GetProperty("name").GetString()??"";return cuda?n.Contains("bin-ubuntu-cuda-12")&&n.EndsWith("-x64.tar.gz"):n.Contains("bin-ubuntu-x64.tar.gz");});if(asset.ValueKind==JsonValueKind.Undefined)continue;await Extract(http,asset,log);if(cuda){var rt=assets.FirstOrDefault(a=>(a.GetProperty("name").GetString()??"").Contains("cudart-")&&(a.GetProperty("name").GetString()??"").Contains("ubuntu-cuda-12")&&(a.GetProperty("name").GetString()??"").EndsWith("-x64.tar.gz"));if(rt.ValueKind!=JsonValueKind.Undefined)await Extract(http,rt,log);}return;}throw new InvalidOperationException("Release Linux compatível não encontrada.");}
 private async Task Extract(HttpClient http,JsonElement asset,Action<string> log){var name=asset.GetProperty("name").GetString()!;log("Baixando "+name);await using var input=await http.GetStreamAsync(asset.GetProperty("browser_download_url").GetString());using var gzip=new GZipStream(input,CompressionMode.Decompress);TarFile.ExtractToDirectory(gzip,LlamaRoot,true);}
}
